def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(1, h-1):
        for c in range(1, w-1):
            if all(grid[r+dr][c+dc] == 2 for dr, dc in ((-1,-1),(-1,1),(1,-1),(1,1))):
                centers.append((r,c))
    # Join facing vertices of consecutive diamond motifs sharing a row or column.
    for r in range(h):
        cs = sorted(c for rr,c in centers if rr == r)
        for a,b in zip(cs, cs[1:]):
            for c in range(a+2, b-1):
                if out[r][c] == 0: out[r][c] = 1
    for c in range(w):
        rs = sorted(r for r,cc in centers if cc == c)
        for a,b in zip(rs, rs[1:]):
            for r in range(a+2, b-1):
                if out[r][c] == 0: out[r][c] = 1
    return out

